pub fn action_definition(slug: &str) -> Option<&'static FoundryActionDefinition> {
    ACTIONS
        .binary_search_by_key(&slug, |action| action.slug)
        .ok()
        .map(|index| &ACTIONS[index])
}
pub fn action_definitions() -> &'static [FoundryActionDefinition] {
    ACTIONS
}
